def top_k_frequent_integers(lists, k):
    freq = {}
    for lst in lists:
        for num in lst:
            freq[num] = freq.get(num, 0) + 1

    heap = []
    for num, count in freq.items():
        heapq.heappush(heap, (count, num))
        if len(heap) > k:
            heapq.heappop(heap)

    result = []
    while heap:
        count, num = heapq.heappop(heap)
        result.append(num)

